import{_ as o,C as r,o as a,c as n,E as d,a2 as i}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"看见问题，不等于有权裁决：从 Anywhere Agents 看 Agent 审计与裁决边界","description":"","frontmatter":{"title":"看见问题，不等于有权裁决：从 Anywhere Agents 看 Agent 审计与裁决边界","date":"2026-08-26","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"Agent 可以发现风险、记录证据并提醒负责人，但怎样保证这些观察不会自动升级成阻塞、批准、驳回或生命周期决定？","summary":"从 CodeFlowMu 一条真实的 EVAL 投影缺陷出发，对照 Yue Zhao 在 Anywhere Agents 中对 advisory audit、agent-io scope 与 review loop 的边界设计，讨论观察权与裁决权为什么必须分开。","sources":"公开一手来源与访问受限的第一方证据范围均在正文列明。","project_relevance":"case-evidence","item_id":"EBR-20260826-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-26-observer-audit-without-adjudication-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-26-observer-audit-without-adjudication.md","filePath":"zh/digital-employee/2026-08-26-observer-audit-without-adjudication.md","lastUpdated":1787803972000}'),s={name:"zh/digital-employee/2026-08-26-observer-audit-without-adjudication.md"};function l(c,e,g,h,p,u){const t=r("ArticleCover");return a(),n("div",null,[d(t,{image:"/assets/covers/daily-2026-08-26-observer-audit-without-adjudication-cover.png",kicker:"数字员工 · 工程研究",title:"看见问题，不等于有权裁决：从 Anywhere Agents 看 Agent 审计与裁决边界",summary:"观察可以深入事实，也可以影响后续工作；但它是否拥有阻塞、批准、驳回或改变生命周期的后果，必须由另一条明确的权力边界决定。",version:"EBR-20260826-02",status:"工程研究 · 2026-08-26",languageHref:"/en/digital-employee/2026-08-26-observer-audit-without-adjudication",languageLabel:"English"}),e[0]||(e[0]=i('<h1 id="看见问题-不等于有权裁决-从-anywhere-agents-看-agent-审计与裁决边界" tabindex="-1">看见问题，不等于有权裁决：从 Anywhere Agents 看 Agent 审计与裁决边界 <a class="header-anchor" href="#看见问题-不等于有权裁决-从-anywhere-agents-看-agent-审计与裁决边界" aria-label="Permalink to &quot;看见问题，不等于有权裁决：从 Anywhere Agents 看 Agent 审计与裁决边界&quot;">​</a></h1><p><strong>一个 Agent 能发现问题，不等于它有权决定任务通过还是驳回。观察是一种事实输入，裁决是一种治理权力。真正可靠的审计系统，不只是“检查得更仔细”，还要把审计结果能产生多大后果写进架构。</strong></p><p>最近我们在 CodeFlowMu 里修复了一条真实的 EVAL 路径；随后继续阅读 Yue Zhao 的 Anywhere Agents issue #35、提交 <code>53bd8fa</code> 以及其中的 <code>style-audit.py</code>，发现两条独立工程路径虽然处理的是不同问题，却在一个边界上出现了相似结构：<strong>观察可以被看见、被记录、被采用，但不能因为它存在，就自动获得阻塞、批准、驳回或改写生命周期的权力。</strong></p><p><strong>CodeFlowMu 是一个本地运行的多 Agent 协作系统，用任务、角色、门禁、报告与审批，把多个 Agent 的工作组织成可追踪、可恢复、可验证的执行链。</strong> 本文讨论的不是“审计 Agent 应不应该有用”，而是一个更窄的问题：<strong>谁有权把一条观察变成业务后果？</strong></p><h2 id="这不是一次偶然交叉" tabindex="-1">这不是一次偶然交叉 <a class="header-anchor" href="#这不是一次偶然交叉" aria-label="Permalink to &quot;这不是一次偶然交叉&quot;">​</a></h2><p>我们对这条研究线的关注早于这次 Anywhere Agents 的工程对照。TMPA 的参考文献 [17] 已经引用 Yi Nian、Aojie Yuan、Haiyue Zhang、Jiate Li 与 Yue Zhao 合著的 <strong>“Auditable Agents”</strong>（arXiv:2604.05485）。那篇工作讨论的是 Agent 可审计性；而从 Yue Zhao 当前公开项目继续往下看，可以看到一条相当连贯的工程研究线。</p><p><code>GRADE</code> 把一次 Agent run 表示成两层图：一层是实际执行顺序，另一层是步骤之间“依赖了什么”的关系，并明确区分 observed、declared 与 inferred 的依赖证据。<code>auditable</code> 又把问题推进到决策记录与恢复：记录一次决定依赖的状态，在 live state 下重新 replay，并在前提已经不成立时通过补偿路径 rollback。<code>awesome-auditable-ai</code> 对 auditability 的定义则非常直接：一个系统最终应能够建立 Agent <strong>做了什么、依赖了什么、为什么这样做，以及这个动作是否正确</strong>。</p><p>这些项目和 CodeFlowMu / TMPA 并不是同一实现链，我们也不把其中任何一个项目当作自己架构的功能背书。但研究问题的重叠非常明显：<strong>仅有执行日志不够；真正可审计的 Agent 系统还需要依赖、来源、责任与决策边界。</strong> TMPA 更关注多 Agent 任务治理和责任结构，CodeFlowMu 把这些问题落到长期运行的任务、门禁、报告和审批链；Yue Zhao 这一侧则持续从运行图、依赖、audit trail、replay / recovery 和实际 Agent tooling 去推进相邻问题。</p><p>因此，本文引用 Anywhere Agents 不是因为某一个 commit 恰好“像 CodeFlowMu”，而是因为它是同一条持续值得跟踪的研究线上，一个非常具体的工程切面：<strong>审计信息怎样变得更强，而裁决权仍然保持明确边界。</strong></p><h2 id="_1-真实故障-7-7-和-4-4-都是绿的-边界仍然错了" tabindex="-1">1. 真实故障：7 / 7 和 4 / 4 都是绿的，边界仍然错了 <a class="header-anchor" href="#_1-真实故障-7-7-和-4-4-都是绿的-边界仍然错了" aria-label="Permalink to &quot;1. 真实故障：7 / 7 和 4 / 4 都是绿的，边界仍然错了&quot;">​</a></h2><p>CodeFlowMu 中的 EVAL 用来做事实核查：读证据、发现矛盾、留下观察。正式验收则属于有权角色。按设计，两者应该分开。</p><p>但一次实际路径暴露了相反的结果：某张生命周期已经完成的任务上存在一份 EVAL 报告，治理快照却把它投影成 <code>acceptance=pending / formal_report_requires_acceptance</code>，页面进一步把它放进“等待 PM 验收”。如果再次点击批准，请求还能进入普通审批路径，最后只是因为任务已经完成而撞上 HTTP 409。</p><p>更重要的是，当这个缺陷存在时，基线测试仍然是绿的：<strong>治理内核 7 / 7，页面终态规则 4 / 4。</strong> 所以问题不是“没有测试”，而是测试没有覆盖一条更深的权限传播链：</p><p><strong>EVAL 写观察 → 投影把它识别成正式交付 → 页面出现待验收语义 → approve / reject 路径可达</strong></p><p>这里最值得警惕的不是某个 Agent 主动越权，而是<strong>系统在投影、API 和页面层替一个观察者增加了权力</strong>。角色边界如果只写在 prompt 或角色说明里，而没有一路保持到状态投影和写操作上，就不是真正的边界。</p><h2 id="_2-多-agent-系统至少要分清四种权力" tabindex="-1">2. 多 Agent 系统至少要分清四种权力 <a class="header-anchor" href="#_2-多-agent-系统至少要分清四种权力" aria-label="Permalink to &quot;2. 多 Agent 系统至少要分清四种权力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>它回答什么</th><th>可以做什么</th><th>不应自动做什么</th></tr></thead><tbody><tr><td>观察</td><td>发现了什么？</td><td>保存事实、矛盾、证据引用</td><td>改变业务结论</td></tr><tr><td>提醒</td><td>谁需要关注？</td><td>形成待关注信息</td><td>把风险直接升级为拒绝</td></tr><tr><td>正式裁决</td><td>这份交付是否接受？</td><td>接受、退回、拒绝并留下理由</td><td>冒充执行事实</td></tr><tr><td>生命周期写入</td><td>任务进入什么状态？</td><td>执行已经获得授权的决定</td><td>自己判断内容“够不够好”</td></tr></tbody></table><p>这四层会互相引用，但不能互相冒充。<strong>观察 ≠ 批准；提醒 ≠ 驳回；生命周期写入 ≠ 业务判断。</strong></p><p>这次修复也没有停在“把按钮隐藏掉”。EVAL 报告在数据和接口层被重新定义为“观察已经记录，不适用正式验收”。重复 approve 或 reject 返回 <code>no_change / already_observed</code>，同时保持几个关键不变量：<code>action_taken=false</code>、不创建业务决定、不触发生命周期动作、生命周期任务文件保持字节级不变；而普通 DEV、QA、OPS 报告原有的正式验收要求不被削弱。</p><p>修复后的验证分别是：治理内核 <strong>8 / 8</strong>、页面终态规则 <strong>6 / 6</strong>、Web Panel / API <strong>109 / 109</strong>、EVAL 显示收口 <strong>18 / 18</strong>。这些数字只证明对应路径，不证明未来所有 UI、插件或外部集成都没有旁路；但它们足以支撑本文最窄的结论：<strong>在已验证路径里，观察可以被确认，却不能借一次重复请求取得裁决权。</strong></p><h2 id="_3-anywhere-agents-更值得注意的-不只是-advisory-only" tabindex="-1">3. Anywhere Agents 更值得注意的，不只是“advisory only” <a class="header-anchor" href="#_3-anywhere-agents-更值得注意的-不只是-advisory-only" aria-label="Permalink to &quot;3. Anywhere Agents 更值得注意的，不只是“advisory only”&quot;">​</a></h2><p>Yue Zhao 的 Anywhere Agents 在 issue #35 中讨论的是另一类问题：写作风格审计原来是一个可选、部分手工拼装的检查。语义规则有时要靠 reviewer 临时写 <code>grep</code>，甚至出现过 shell locale 导致 grep 什么都没有匹配，而“检查根本没跑成功”和“文本确实没有问题”在输出上看起来一样的情况。</p><p>issue 最初提出了一个很自然的方向：把检查做成固定脚本，让它按内容触发，并像 verification 一样留下明确的 <code>Style status</code>。但后续校准暴露出另一个风险：<strong>如果把机械 style findings 直接送进正式 review loop，它们就可能从“提示”升级成“必须解决的问题”。</strong> 在一段长 session 中，review prompt 本身可以收到 7 到 12 条 RULE-12 提示；而 RULE-12 这种“句子超过 30 个词”的规则没有稳定的固定点——拆一句长句，可能又产生另一句长句。若每次修文都会产生新 diff、再触发一轮 review，机械风格检查就可能把本来已经可以 PASS 的 review 一直拖住。</p><p>所以后来形成的 maintainer constraint 非常明确：</p><blockquote><p><strong>style audit 必须可见，但绝不能有能力把 review loop 卡住。</strong></p></blockquote><p>这不是一句文档承诺，而是被做成了结构：audit 放在 Round 1 之前的 pre-flight 或 PASS 之后的 pre-commit 固定点；正常审计结果不通过退出码阻塞；findings 不进入 reviewer prompt，不进入 Round history，也不进入 final verdict。<code>CLEAN</code>、<code>FINDINGS: N</code>、<code>SKIPPED</code>、<code>FAILED</code> 都可以被记录，但这个值本身不获得 verdict 权力。</p><p>这一步很重要，因为它把两个经常被混在一起的问题拆开了：</p><blockquote><p><strong>“这个检查是否发生、结果是否可见”是一件事；“这个结果是否有资格阻塞流程”是另一件事。</strong></p></blockquote><h2 id="_4-agent-io-的细节说明-后果越强-信任门槛越高" tabindex="-1">4. <code>agent-io</code> 的细节说明：后果越强，信任门槛越高 <a class="header-anchor" href="#_4-agent-io-的细节说明-后果越强-信任门槛越高" aria-label="Permalink to &quot;4. `agent-io` 的细节说明：后果越强，信任门槛越高&quot;">​</a></h2><p>提交 <code>53bd8fa</code> 还做了另一个很有意思的边界设计。原来的 writing-style guard 主要按文件扩展名判断文本，于是 Agent 真正在写的 prose 和它只是携带的 dispatch prompt、review output 都可能被当成同一类内容。作者在 34 份 session transcript 中报告了 2,227 条 advisory，并发现不少 prose-extension 文件其实位于承载 review-loop 中间文本的 scratch 区域。</p><p>解决办法之一是让调用方用 <code>agent-io</code> 标记 carried text。但 Anywhere Agents 并没有让所有 guard 对这个标记给予同等信任：</p><table tabindex="0"><thead><tr><th>Anywhere Agents 中的动作</th><th>错误豁免的后果</th><th>对 <code>agent-io</code> 的信任</th></tr></thead><tbody><tr><td>advisory 提示</td><td>最坏多漏一条提示</td><td>可以较宽松地接受标记</td></tr><tr><td>deny gate</td><td>可能绕过真实写入禁令</td><td>只在临时根目录、且其中不包含 repository 时接受，并先解析 symlink</td></tr></tbody></table><p>这背后的原则比具体目录名更值得关注：</p><blockquote><p><strong>后果越强，所需的授权与证据门槛就应该越高。</strong></p></blockquote><p>如果一个标记只影响“要不要多提示一句”，信任成本较低；如果它会决定“能不能绕过 deny”，同一个标记就不能成为一键逃生口。Anywhere Agents 甚至明确考虑了 <code>repo/agent-io/proposal.md</code> 这种看似合法、实际可能把真实 prose 伪装成 carried text 的路径。</p><p><code>style-audit.py</code> 里还有同样的证据意识：它审的是 <strong>staged blob</strong>，不是当前 working tree，因为“用 staged 行号过滤 working-tree 内容”可能既漏掉真正准备提交的问题，也把未暂存内容错误归到本次提交。该提交报告 whole-file 359 条历史 findings，在只看本次改动行后收敛到 2 条。这个数字是 Anywhere Agents 自己的工程测量，本文没有独立复现；真正重要的是方法：<strong>被审计的对象必须和真正要被 review 的对象一致。</strong></p><h2 id="_5-两条独立路径-为什么会在同一个边界上收敛" tabindex="-1">5. 两条独立路径，为什么会在同一个边界上收敛？ <a class="header-anchor" href="#_5-两条独立路径-为什么会在同一个边界上收敛" aria-label="Permalink to &quot;5. 两条独立路径，为什么会在同一个边界上收敛？&quot;">​</a></h2><p>CodeFlowMu 的问题发生在任务治理层，Anywhere Agents 的问题发生在写作 guard 与 review loop 层。两者不应被说成同一种实现，也不存在“Anywhere Agents 证明了 CodeFlowMu 正确”。但把它们并排看，会看到一个很清楚的共同结构：</p><table tabindex="0"><thead><tr><th>Anywhere Agents</th><th>CodeFlowMu</th></tr></thead><tbody><tr><td>style audit 产生 findings</td><td>EVAL 产生 observation</td></tr><tr><td>audit 结果可见，但不进入 verdict</td><td>observation 可记录，但不成为 formal acceptance</td></tr><tr><td><code>Style status</code> 可以存在，但值不阻塞 PASS</td><td><code>already_observed / no_change</code> 不产生 business decision</td></tr><tr><td>高后果 deny gate 要求更强的 <code>agent-io</code> 信任边界</td><td>accept / reject / lifecycle write 要求更强的正式权限</td></tr><tr><td>staged blob + changed lines 保证审计对象一致</td><td>lifecycle 文件 byte-identical 证明 observer 动作没有改写任务状态</td></tr></tbody></table><p>我们在 CodeFlowMu 里还遇到过另一个容易混淆的方案：既然 Runtime 不应替业务裁决，是否可以除少数负面清单外一律 <code>default allow</code>？这个方案在进入产品代码前被 BLOCKED。原因同样是：<strong>“默认允许”仍然是一种裁决。</strong> 非裁决不是永远说 Yes，而是只对自己真正拥有机械判断权的事实作决定。</p><p>因此，一个成熟的辅助层不应该只有 <code>ALLOW / DENY</code>，还需要 <code>OBSERVE / ATTENTION / REVIEW REQUIRED</code> 这样的语义，让“我发现了问题”和“我有权替团队下结论”保持正交。</p><h2 id="_6-下一步-来源标签能不能传播-但始终不等于权限" tabindex="-1">6. 下一步：来源标签能不能传播，但始终不等于权限？ <a class="header-anchor" href="#_6-下一步-来源标签能不能传播-但始终不等于权限" aria-label="Permalink to &quot;6. 下一步：来源标签能不能传播，但始终不等于权限？&quot;">​</a></h2><p>Anywhere Agents 已经在非常具体的工程位置区分了 Agent <strong>authored</strong> 的文本与 <strong>carried</strong> 的文本；CodeFlowMu 当前关注的是 <strong>observed</strong> 的事实与 <strong>formally decided</strong> 的业务结论。两边都还可以继续往前走，但这里最值得研究的不是给 observer 更多权力，而是给证据更多可追踪关系。</p><p>一个可能的问题是：<code>authored / carried / observed / generated</code> 这样的来源类型，是否应该随着 Tool Call、Agent handoff 和 review chain 一起传播？如果传播，它们又怎样始终与“谁有权阻塞、批准、驳回或改变状态”保持正交？</p><p>对 CodeFlowMu 来说，未来更完整的责任链可以是：</p><p><strong>观察 → 被哪次正式 review 引用 → reviewer 如何采纳或不采纳 → 正式决定 → 受控生命周期写入</strong></p><p>而不是：</p><p><strong>观察 → 状态变化</strong></p><p>前者保留了审计价值，也保留了责任归属。后者看起来更“自动”，实际却把最关键的治理边界抹掉了。</p><h2 id="结论-审计能力越强-越需要清楚自己不能决定什么" tabindex="-1">结论：审计能力越强，越需要清楚自己不能决定什么 <a class="header-anchor" href="#结论-审计能力越强-越需要清楚自己不能决定什么" aria-label="Permalink to &quot;结论：审计能力越强，越需要清楚自己不能决定什么&quot;">​</a></h2><p>一个好的审计 Agent 不应该因为没有最终签字权就变得“弱”。它完全可以更深入地检查证据、发现矛盾、保留来源、提示风险，甚至让正式决策者改变判断。真正需要限制的是另一件事：<strong>观察本身不能自动继承业务后果。</strong></p><p>Anywhere Agents 的 issue #35 和 <code>53bd8fa</code> 很有价值的地方，是它没有只解决“怎样把 style audit 跑起来”，还继续追问了“怎样让 audit 可见，却不能把 review loop 变成自己的控制对象”。CodeFlowMu 的 EVAL 缺陷则从另一边说明：即使 observer 自己没有 approve 权限，投影、UI 和 API 也可能把裁决语义重新接回来。</p><p>两边共同提醒我们：</p><blockquote><p><strong>审计不是裁决的低配版本。它应该是一条独立的证据通道。</strong></p></blockquote><blockquote><p><strong>看见问题，不等于有权裁决；后果越强，所需的授权与证据边界就应该越严格。</strong></p></blockquote><hr><h2 id="公开证据" tabindex="-1">公开证据 <a class="header-anchor" href="#公开证据" aria-label="Permalink to &quot;公开证据&quot;">​</a></h2><ul><li><a href="/joinwell52/evidence/execution-boundary-20260826/v2/case-a2-observer-semantic-trace.csv"><strong>查看 A2 基线、修复和重复操作记录（CSV）</strong></a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/transcript-a2.md" target="_blank" rel="noreferrer"><strong>查看 A2 脱敏测试摘录（GitHub）</strong></a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/claim-evidence-map.csv" target="_blank" rel="noreferrer"><strong>核对本文主张对应哪一条证据（GitHub）</strong></a></li><li><a href="/joinwell52/zh/digital-employee/2026-08-26-execution-boundary-evidence-data"><strong>查看公开、脱敏的 Execution Boundary 四案例数据包</strong></a></li></ul><h2 id="来源与证据边界" tabindex="-1">来源与证据边界 <a class="header-anchor" href="#来源与证据边界" aria-label="Permalink to &quot;来源与证据边界&quot;">​</a></h2><h3 id="yue-zhao-相关公开研究与工程" tabindex="-1">Yue Zhao 相关公开研究与工程 <a class="header-anchor" href="#yue-zhao-相关公开研究与工程" aria-label="Permalink to &quot;Yue Zhao 相关公开研究与工程&quot;">​</a></h3><ul><li><a href="https://arxiv.org/abs/2604.05485" target="_blank" rel="noreferrer"><strong>“Auditable Agents”</strong></a>，Yi Nian、Aojie Yuan、Haiyue Zhang、Jiate Li、Yue Zhao，2026。TMPA 参考文献 [17] 已引用该工作。本文只用它说明我们持续关注的研究主题，不将后续仓库简单视作该论文的直接实现。</li><li><a href="https://github.com/yzhao062/grade" target="_blank" rel="noreferrer"><strong>GRADE</strong></a>：本文引用其 execution / dependency 双层 run representation，以及 observed / declared / inferred 的依赖证据区分作为研究背景。</li><li><a href="https://github.com/yzhao062/auditable" target="_blank" rel="noreferrer"><strong>auditable</strong></a>：本文引用其 decision dependency capture、live-state replay 与 rollback 方向作为研究背景。</li><li><a href="https://github.com/yzhao062/awesome-auditable-ai" target="_blank" rel="noreferrer"><strong>Awesome Auditable AI</strong></a>：本文引用其对 auditability / reliability 问题空间的公开整理作为研究背景。</li><li><a href="https://github.com/yzhao062/anywhere-agents/issues/35" target="_blank" rel="noreferrer"><strong>Anywhere Agents issue #35</strong></a>：本文引用其从“可选、手工审计”走向确定性脚本，以及后续对 <code>Style status</code>、review-body 注入和 review-loop 阻塞风险的讨论。</li><li><a href="https://github.com/yzhao062/anywhere-agents/commit/53bd8fa43c7339ae9958c03c55434fac7baddaf3" target="_blank" rel="noreferrer"><strong>Anywhere Agents commit <code>53bd8fa</code></strong></a>，2026-08-25：本文引用其 <code>agent-io</code> scope、不同 guard 的不同信任深度，以及 advisory audit 不进入 reviewer prompt、Round history 和 final verdict 的设计。</li><li><a href="https://github.com/yzhao062/anywhere-agents/blob/53bd8fa43c7339ae9958c03c55434fac7baddaf3/skills/implement-review/scripts/style-audit.py" target="_blank" rel="noreferrer"><strong><code>style-audit.py</code>（对应提交版本）</strong></a>：用于核对 staged-blob 审计、changed-line scoping 和“advisory by construction”的实现说明。</li></ul><p>本文提到的 34 份 session transcript、2,227 条 advisory、359→2 findings 等数字均为 Anywhere Agents 作者在对应 issue / commit 中报告的工程测量，本文没有独立复现，不把它们解释为通用准确率或效果证明。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>本文关于 CodeFlowMu 的结论只适用于公开 A2 证据覆盖的命名路径。证据支持：7 / 7 与 4 / 4 的基线没有覆盖已观察缺陷；修复后治理内核 8 / 8、页面规则 6 / 6、Web Panel / API 109 / 109、EVAL 收口 18 / 18；重复 EVAL approve / reject 不产生业务决定、不触发生命周期动作，并保持生命周期任务文件不变。</p><p>这些证据<strong>不能证明</strong>未来所有 UI、插件和外部集成都不存在旁路，也不能证明 EVAL 的观察永远正确，更不能证明完整的 provenance / responsibility chain 已经实现。原始日志、任务正文和本机路径不公开；研究结论应与对应版本、测试集合和证据边界一起阅读。</p>',65))])}const A=o(s,[["render",l]]);export{y as __pageData,A as default};
